	name = "Français",
	listed = true,
	plural = function(n)
		local i = math.floor(n)
		if i == 0 or i == 1 then
			return "one"
		end
		if n == i and i % 1000000 == 0 then
			return "many"
		end
		return "other"
	end,
	decimal = ",",
	thousands = "",
})
